//! Client bindings for the KDE protocols the bridge uses, generated by
//! `wayland-scanner` from the vendored XMLs in `bridge/protocols/` (provenance
//! and SHA-256 in `bridge/protocols/README.md`). This is the single place for
//! KDE protocol bindings; add further KDE protocols here as new submodules.
//!
//! * [`fake_input`]: `org_kde_kwin_fake_input` v6, used by `kwin_input`.
//! * [`screencast`]: `zkde_screencast_unstable_v1` v6 (bind v6 for the `serial`
//!   event, which is PipeWire's `object.serial` for `target.object`).
//! * [`output_device`]: `kde_output_device_registry_v2` (KWin rejects
//!   versions < 21) announcing `kde_output_device_v2` objects.
//!
//! `ext_data_control_v1` (clipboard) comes from the `wayland-protocols` crate
//! (`wayland_protocols::ext::data_control::v1`), not from here.
#![allow(
    dead_code,
    non_camel_case_types,
    non_upper_case_globals,
    unused_imports,
    clippy::all,
    missing_docs
)]

pub mod fake_input {
    use wayland_client;
    use wayland_client::backend as wayland_backend;
    use wayland_client::protocol::*;
    pub mod __interfaces {
        use wayland_client::backend as wayland_backend;
        use wayland_client::protocol::__interfaces::*;
        wayland_scanner::generate_interfaces!("protocols/fake-input.xml");
    }
    use self::__interfaces::*;
    wayland_scanner::generate_client_code!("protocols/fake-input.xml");
}

pub mod screencast {
    use wayland_client;
    use wayland_client::backend as wayland_backend;
    use wayland_client::protocol::*;
    pub mod __interfaces {
        use wayland_client::backend as wayland_backend;
        use wayland_client::protocol::__interfaces::*;
        wayland_scanner::generate_interfaces!("protocols/zkde-screencast-unstable-v1.xml");
    }
    use self::__interfaces::*;
    wayland_scanner::generate_client_code!("protocols/zkde-screencast-unstable-v1.xml");
}

pub mod output_device {
    use wayland_client;
    use wayland_client::backend as wayland_backend;
    use wayland_client::protocol::*;
    pub mod __interfaces {
        use wayland_client::backend as wayland_backend;
        use wayland_client::protocol::__interfaces::*;
        wayland_scanner::generate_interfaces!("protocols/kde-output-device-v2.xml");
    }
    use self::__interfaces::*;
    wayland_scanner::generate_client_code!("protocols/kde-output-device-v2.xml");
}
